3	/// An always-available "remote keyboard" docked under the focused terminal.
4	///
5	/// The terminal pane already renders cmux/Claude's own input line, so this bar
6	/// is deliberately styled as distinct keyboard chrome (not glass-terminal) to
7	/// read as *your* input bridge rather than a second prompt. It stays collapsed
8	/// to a slim field until tapped, then reveals command autocomplete and a
9	/// control-key row. It clears on send — the terminal's output remains the one
10	/// source of truth for what was typed.
11	struct TerminalInputBar: View {
12	    let surfaceTitle: String
13	    /// Reflects keyboard/compose focus up to the parent so it can give the
14	    /// focused terminal the whole screen while typing.
15	    @Binding var isActive: Bool
16	    var onSendText: (String) -> Void   // send text only (no newline)
17	    var onSendEnter: (String) -> Void  // send text + Enter (run it)
18	    var onSendKey: (String) -> Void    // send a control/navigation key
19	
20	    @State private var draft = ""
21	    @FocusState private var focused: Bool
22	    @StateObject private var commandDict = CommandDictionary()
23	    // Landscape on iPhone reports a compact vertical size class. There the
24	    // keyboard eats most of the height, so the bar shrinks to a single chip
25	    // row + inline dismiss to leave room for the terminal.
26	    @Environment(\.verticalSizeClass) private var vSizeClass
27	    private var isCompact: Bool { vSizeClass == .compact }
28	
29	    // Label, key-name sent to the bridge (matches SendTextView conventions).
30	    private let controlKeys: [(String, String)] = [
31	        ("esc", "Escape"), ("⌃C", "ctrl+c"), ("⌃D", "ctrl+d"),
32	        ("⇥", "Tab"), ("↑", "Up"), ("↓", "Down"), ("←", "Left"), ("→", "Right"),
33	    ]
34	
