36	        VStack(spacing: isCompact ? 4 : 6) {
37	            if focused {
38	                if isCompact {
39	                    // One merged, scrollable row keeps the footprint minimal.
40	                    compactChipsRow
41	                } else {
42	                    header
43	                    suggestionsRow
44	                    controlKeyRow
45	                }
46	            }
47	            composeRow
