49	        .padding(.horizontal, 10)
50	        .padding(.vertical, isCompact ? 6 : 8)
51	        .background(
52	            RoundedRectangle(cornerRadius: 14)
53	                .fill(.ultraThinMaterial)
54	                .environment(\.colorScheme, .dark)
55	                .overlay(
56	                    RoundedRectangle(cornerRadius: 14)
57	                        .stroke(.white.opacity(0.12), lineWidth: 0.5)
58	                )
59	        )
60	        .padding(.horizontal, 8)
61	        .animation(.easeInOut(duration: 0.18), value: focused)
62	        .onChange(of: focused) { _, active in isActive = active }
63	        // If the bar is torn down while focused (quick actions open, the focused
64	        // surface closes or becomes a browser, tab switch), `.onChange(of:focused)`
65	        // won't fire — so reset here, or the parent leaves the workspace bar and
66	        // secondaries hidden forever.
67	        .onDisappear { isActive = false }
68	    }
