189	
190	    // Suggestions + control keys merged into a single scrollable row so the
191	    // whole bar is just this row + the compose row when the keyboard is up.
192	    private var compactChipsRow: some View {
193	        ScrollView(.horizontal, showsIndicators: false) {
194	            HStack(spacing: 6) {
195	                ForEach(commandDict.suggestions(for: currentWord), id: \.self) { cmd in
196	                    suggestionChip(cmd)
197	                }
198	                ForEach(controlKeys, id: \.1) { label, key in
199	                    controlChip(label: label, key: key)
200	                }
201	            }
202	            .padding(.horizontal, 2)
203	        }
204	        .frame(height: 30)
205	    }
