207	    private func suggestionChip(_ cmd: String) -> some View {
208	        Button {
209	            insertSuggestion(cmd)
210	        } label: {
211	            Text(cmd)
212	                .font(.system(size: 12, weight: .medium, design: .monospaced))
213	                .foregroundStyle(.white.opacity(0.85))
214	                .padding(.horizontal, 10)
215	                .padding(.vertical, 5)
216	                .background(Capsule().fill(.white.opacity(0.1)))
217	        }
218	    }
