220	    private func controlChip(label: String, key: String) -> some View {
221	        Button {
222	            onSendKey(key)
223	        } label: {
224	            Text(label)
225	                .font(.system(size: 13, weight: .medium, design: .monospaced))
226	                .foregroundStyle(.white.opacity(0.75))
227	                .frame(minWidth: 34)
228	                .padding(.vertical, 6)
229	                .background(RoundedRectangle(cornerRadius: 7).fill(.white.opacity(0.08)))
230	        }
231	    }
232	
233	    // MARK: - Actions
234	
235	    private func send(withEnter: Bool) {
236	        let text = draft
237	        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
238	        learnCommand(text)
239	        if withEnter {
240	            onSendEnter(text)
241	        } else {
242	            onSendText(text)
243	        }
244	        draft = ""
245	        // Keep the keyboard up so the user can fire off several commands.
246	    }
247	
248	    private func insertSuggestion(_ command: String) {
249	        let parts = draft.split(separator: " ", omittingEmptySubsequences: false).map(String.init)
250	        if parts.isEmpty {
251	            draft = command + " "
252	        } else {
253	            var updated = parts
254	            updated[updated.count - 1] = command
255	            draft = updated.joined(separator: " ") + " "
256	        }
257	    }
258	
259	    private func learnCommand(_ input: String) {
260	        let firstWord = input.trimmingCharacters(in: .whitespacesAndNewlines)
261	            .split(separator: " ").first.map(String.init) ?? ""
262	        if !firstWord.isEmpty { commandDict.add(firstWord) }
263	    }
264	}
